"""Grant scoped chromVAR core/background credit from frozen public workflows and five primary-source reviews."""
import hashlib,json
from pathlib import Path
from catalog_source_integrity import verify_source,reverse_delta
from catalog_fixed_cohort import verify_fixed_cohort
from signac_scan_evidence import unpack
def read(p):return json.loads(p.read_bytes())
def pin(p):return dict(bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def verify(root,data):
    root=Path(root);data=Path(data);folder=root/'docs/literature/chromvar-tools-development';proof=read(folder/'VALIDATION.json');assert proof['status']=='passed-public-chromVAR-main-workflows-and-paper-source-correspondence' and pin(folder/'controls.zip')==proof['archive'] and pin(folder/'WARNINGS.md')==proof['warnings_document'];files=unpack(folder/'controls.zip',proof)
    for name,value in proof['source_pins'].items():
        raw=files['current-source/'+name];assert dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())==value;verify_source(root,data,name,value['sha256'])
    assert proof['normal_Gradle_executableJar'] and proof['root_dispatch_available'] and proof['chromVAR_and_non_study_parent_file_entries_unchanged'] and len(proof['carried_existing_canonical_study_class_changes'])==12
    assert (proof['original_public_main_BACKGROUND_fits'],proof['native_public_main_DEVIATIONS'],proof['actual_main_capture_verifications'],proof['actual_main_dependency_skip'],proof['actual_main_failed_capture_rejections'],proof['literal_public_capture_verifications'])==(2,3,27,1,3,6)
    assert (proof['paper_source_numeric_method_comparisons'],proof['paper_source_background_protocols'],proof['paper_source_case_profile_protocols'])==(306,45,102) and proof['paper_1_5_0_commit_unknown'] and proof['prepublication_reference_commit']=='3236dcc515efa01ce54114aee03b227466168126'
    bridge=read(data/'chromvar-dispatch-shared-source-compatibility.json')['paths'][0];assert len(bridge['edits'])==2 and reverse_delta(files['current-source/'+bridge['path']],bridge)==files['build/literature-review/signac-runtime/chromvar-public-workflow-1/JLinAlgCli.before.java']
    parent=root/'docs/literature/chromvar-background-development';prior=read(parent/'VALIDATION.json');assert pin(parent/'VALIDATION.json')==proof['parent_background_validation'] and pin(parent/'controls.zip')==proof['parent_background_archive'];unpack(parent/'controls.zip',prior)
    for n,v in prior['source_pins'].items():verify_source(root,data,n,v['sha256'])
    assert (prior['original_background_and_RNG_request_comparisons'],prior['retained_source_failure_requests'],prior['captured_request_verifications'],prior['failed_source_capture_rejections'],prior['rehashed_single_change_rejections'],prior['actual_dependency_skips'],prior['normal_Gradle_native_tests'])==(18,12,54,36,42,2,369) and prior['actual_owned_timeout_cleanup'] and prior['known_coordinated_forgery_structurally_accepted']==3
    assert not any(proof[k] for k in ['historical_whole_packages_executed','independent_native_RNG_replay','installed_DLL_source_authentication','ArchR_pipeline_available','full_Signac_workflow_available','released','pushed','deployed','whole_goal_complete'])
    artifact=root/proof['artifact']['path']
    if artifact.exists():assert pin(artifact)=={k:proof['artifact'][k] for k in ['bytes','sha256']}
    roles=read(data/'chromvar-role-coverage.json');assert roles['applied'] and (roles['prior_reviews_preserved'],roles['new_reviews'],roles['total_reviews'],roles['supporting_pointers'],roles['reviewed_roles'])==(827,5,832,255,5) and roles['P099_explicit_1_16_0_corrected'] and roles['ArchR_workflow_separate'] and roles['paper_1_5_0_commit_unknown'] and not roles['implementation_promoted'];verify_source(root,data,'tools/literature/reviewed-uses.json',roles['reviews_sha256'])
    reviews=[r for r in read(root/'tools/literature/reviewed-uses.json')['reviews'] if r['tool_id']=='chromvar'];draft=read(root/'tools/literature/chromvar-use-reviews.json');assert len(reviews)==5 and reviews==[r['review'] for r in draft];papers=read(data/'papers.json');verify_fixed_cohort(root,data,papers);observed={p['paper_id']:p for p in papers if any(t['tool_id']=='chromvar' for t in p['tools'])};assert set(observed)=={'P039','P051','P092','P099','P225'}
    for review in reviews:
        paper=next(p for p in observed.values() if p['pmcid']==review['pmcid']);tool=next(t for t in paper['tools'] if t['tool_id']=='chromvar');assert paper['doi']==review['doi'] and all(tool[k]==review[k] for k in ['evidence_paragraph_sha256','use_summary','implementation_scope_note','version_reported_near_name'])
    return proof
def chromvar_metadata(root,data):
    p=verify(root,data)
    return dict(implementation_status='upstream-adapter-validated',implementation_source='src/main/java/org/jlinalg/cli/ChromVarToolsCli.java',coverage_note='New scoped chromvar-tools integration: native GC/expectations/deviations plus original matched-background sampling. Five primary uses reviewed; ArchR and complete paper pipelines remain separate.',implementation_scope='Public chromvar-tools --request UTF8_JSON routes BACKGROUND, native DEVIATIONS and portable VERIFY. Native sparse count preparation, canonical-base reference GC, supplied annotation/background scoring, expectation/group/value-kind contracts and fraction metadata; original source/background public-interface replay requires exact R4.6.1/chromVAR1.34.1 dependencies and explicit seed/iteration/bandwidth/bin limits. Request profiles remain1.16.0-source/1.34.1-package. Retained1.28.0 and pre-publication upstream1.5.0 core functions match; historical whole packages and P225 exact commit are not reconstructed. Complete checked reference-to-background-to-deviation example; typed bias route and native prepared-background-only mode. No automatic installation, reference/motif acquisition, filtering, imputation, historical substitution, whole Signac/ArchR workflow, downstream rescaling/aggregation/correlation or biological certification. Read CHROMVAR_TOOLS.md and examples/chromvar-tools/README.md.',validation_note='Normal Gradle main executable with inherited chromVAR bytes preserved. Two actual public R fits on WindowsJava21/25, three public native analyses including LinuxJava21,27 actual-main verifications and six literal example verifications pass. Additional paper-edition306 method comparisons and45 source/public background protocols match every original numeric field/kind and full RNG states on current dependencies. Parent18 successful/12 failed source requests,54 portable verifications,42 rehashed single-change rejections, two real dependency skips, owned timeout cleanup and369 normal native tests are retained. VERIFY is structural: coordinated fabricated worker/published indices with recomputed hashes are accepted by design and explicitly demonstrated; it does not rerun sampling or authenticate execution. P0991.16.0 corrected; P092 ArchR separate; P2251.5.0 commit unknown. No full-paper or biological-accuracy claim.',project_adapter_available=True,canonical_adapter_available=False,development_adapter_cli='chromvar-tools',development_candidate=p['artifact']['path'],development_candidate_sha256=p['artifact']['sha256'],engine_status=dict(native_GC_and_deviations='native-subset-validated',original_current_background='upstream-adapter-validated',historical_whole_packages='not-certified',ArchR_pipeline='separate-pending',independent_RNG_replay='not-implemented'))
CHROMVAR_WARNING='''## chromVAR: native scoring, original backgrounds and required recovery

**Current workspace source includes chromvar-tools; older canonical/released JARs lack the command.** Read CHROMVAR_TOOLS.md, chromvar-tools-development/VALIDATION.json and examples/chromvar-tools/README.md. Use explicit BACKGROUND, DEVIATIONS or VERIFY requests and NEW outputs. Native GC/deviation scoring uses Java and exact supplied populations; source NA/NaN/Inf remain explicit.

**SKIP3: unavailable/forbidden requirements mean skip dependent analysis.** Original backgrounds need R4.6.1, chromVAR1.34.1, Matrix1.7.5, nabor0.5.0, Rcpp1.1.2, RcppArmadillo15.6.2-1 and jsonlite2.0.0 with dependencies in declared permitted private paths. Set the four runtime fields. No automatic installation occurs. Do not proceed without a valid separately prepared background. **FAIL2 means no result admitted:** preserve captures/partials, inspect WARNINGS.md, analysis-status.json, manifest, diagnostics and worker logs, correct the named reference/input/covariance/source/capacity/process error and retry into NEW paths.

**VERIFY checks consistency, not independent sampling or authenticity.** It recomputes native preparation and checks source, inputs, settings, index ranges, worker/published agreement, recorded RNG states and inventory. Coordinated fabricated worker/published indices after rehashing pass these structural checks; this limitation is tested and retained. Hashes do not prove execution or biology.

**Preserve paper boundaries.** Five primary uses are reviewed. P099 explicitly reports1.16.0; P092 uses ArchR addBgdPeaks/addDeviationsMatrix and is not a validated direct R/ArchR reconstruction. P225 reports1.5.0 without its commit: a pre-publication official reference snapshot matches the four validated R functions, with only a terminal-LF C++ difference, but its exact checkout and historical dependencies are unknown. Supported request profiles remain1.16.0-source/1.34.1-package. Signac/Seurat wrappers, BSgenome containers, motif resources/scanning, subsampling, rescale0–10, aggregation and expression/spatial correlations remain separate. Cell Ranger remains excluded.

**Validation:** normal Gradle executable; two public original fits, three native analyses,27 public capture verifications and six literal example verifications. Paper-edition306 method and45 background protocols match original fields/kinds and RNG states on current dependencies. Parent source/error, dependency-skip, timeout and369 native controls are preserved. Actual R fits were Windows clients; native/VERIFY also passed Linux. These are scoped synthetic/source controls, not full-paper or biological validation. This work remains local and unpushed.

'''
